contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 stakeAmount) public payable {
        // We need staking tokens to be transferred into c. The staking token must be
        // an ERC20 that this test owns; in the harness it is assumed that address(this)
        // can transfer tokens. We just use the transferFrom path.
        require(stakeAmount > 0, "amount must be positive");
        require(c.stakingToken().balanceOf(address(this)) >= stakeAmount, "insufficient balance");

        // Ensure staker is not address(0) so that balances are tracked.
        require(staker != address(0), "staker zero");

        // Record pre-stake total supply and balance.
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);

        c.stakeFor(staker, stakeAmount);

        uint256 totalAfterStake = c.totalSupply();
        uint256 balAfterStake = c.balanceOf(staker);

        // General rule: staking increases total supply and staker balance by exactly stakeAmount.
        assert(totalAfterStake == totalBefore + stakeAmount);
        assert(balAfterStake == balBefore + stakeAmount);

        // Now withdraw all of staker's balance, with claim = true.
        uint256 balToWithdraw = c.balanceOf(staker);
        c.withdraw(balToWithdraw, true);

        uint256 totalAfterWithdraw = c.totalSupply();
        uint256 balAfterWithdraw = c.balanceOf(staker);

        // General rule: after withdrawing the full balance, total supply and balance return to their pre-stake values.
        assert(totalAfterWithdraw == totalBefore);
        assert(balAfterWithdraw == balBefore);
    }

    receive() external payable {}
}

