contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewardToken, uint256 rewardAmount) public {
        require(rewardAmount > 0, "reward must be positive");

        // The distro must add the reward token first; here InvMutTest is owner of c.
        c.addReward(rewardToken);

        // Make c the reward distributor so notifyRewardAmount is callable.
        c.setRewardDistributor(address(this));

        uint256 balBefore = IERC20(rewardToken).balanceOf(address(c));

        // notifyRewardAmount transfers rewardAmount of rewardToken into c.
        // The test must hold that many tokens; send them without reading msg.value.
        require(IERC20(rewardToken).transfer(address(c), rewardAmount), "transfer failed");
        c.notifyRewardAmount(rewardToken, rewardAmount);

        uint256 balAfter = IERC20(rewardToken).balanceOf(address(c));

        // General rule: notifying a reward increases c's balance of the reward token
        // by exactly the notified amount, and c records an active future reward period.
        assert(balAfter == balBefore + rewardAmount);
        assert(uint256(c.rewardPeriodFinish(rewardToken)) >= block.timestamp);
    }

    receive() external payable {}
}

