contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount > 0);

        // Setup: stake `amount` (only valid if stakingToken approve/transferFrom works)
        // We read before-balances from the public surface
        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool stakeReverted;
        try c.stake(amount) { stakeReverted = false; } catch { stakeReverted = true; }

        if (!stakeReverted) {
            // general rule: principal is conserved exactly
            assert(c.balanceOf(address(this)) == balBefore + amount);
        } else {
            // if the stake reverted, state must not have changed
            assert(c.balanceOf(address(this)) == balBefore);
            assert(c.totalSupply() == totalBefore);
        }
    }
    receive() external payable {}
}

