        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialBalance = c.balanceOf(address(this));

        // Perform stake
        c.stake(stakeAmount);

        // After staking, balance and total supply must increase by exactly stakeAmount
        uint256 afterStakeTotalSupply = c.totalSupply();
        uint256 afterStakeBalance = c.balanceOf(address(this));

        assert(afterStakeTotalSupply == initialTotalSupply + stakeAmount);
        assert(afterStakeBalance == initialBalance + stakeAmount);

        // Optionally withdraw
        if (doWithdraw) {
            require(withdrawAmount > 0 && withdrawAmount <= afterStakeBalance, "invalid withdraw amount");
            c.withdraw(withdrawAmount, false);
            uint256 afterWithdrawTotalSupply = c.totalSupply();
            uint256 afterWithdrawBalance = c.balanceOf(address(this));
            assert(afterWithdrawTotalSupply == afterStakeTotalSupply - withdrawAmount);
            assert(afterWithdrawBalance == afterStakeBalance - withdrawAmount);
        }
    }

    receive() external payable {}
}

