        uint256 afterTotal = c.totalSupply();

        if (!reverted) {
            assert(afterBal == beforeBal + amount);
            assert(afterTotal == beforeTotal + amount);
        } else {
            assert(afterBal == beforeBal);
            assert(afterTotal == beforeTotal);
        }
