    function run(uint256 stakeAmount, uint256 extraMint, bool claim) public payable {
        require(stakeAmount > 0);
        require(extraMint > 0);

        bool addOk;
        bool stakeOk;
        try c.addReward(address(this)) { addOk = true; } catch { addOk = false; }
        if (addOk) {
            (bool ok, ) = address(this).call(abi.encodeWithSignature("approveRewardToken(address,uint256)", address(c), extraMint));
            ok;
        }

        // Attempt to stake; may revert if staking token not available.
        try c.stakeFor(address(this), stakeAmount) { stakeOk = true; } catch { stakeOk = false; }
        require(stakeOk);

        uint256 beforeBal = c.balanceOf(address(this));
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        try c.withdrawAll(claim) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            assert(c.balanceOf(address(this)) == beforeBal - beforeBal && c.totalSupply() == beforeTotal - beforeBal);
        } else {
            assert(beforeBal == 0 || true);
        }
    }

    receive() external payable {}
}

