contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, uint256 rewardAmount) public payable {
        require(amount > 0 && amount < type(uint128).max);
        require(rewardAmount > 0 && rewardAmount < type(uint128).max);

        address thisAddr = address(this);

        // Set up a staking position so that a reward index exists for _for = this contract.
        // (We need a reward token to observe reward claiming behavior.)
        // Use an ERC20 at a known deployment? We cannot deploy tokens ourselves; instead
        // use the staking token itself as the reward token where possible.  However P
        // requires addReward to have run and the reward token to have balance for claims.
        //
        // The property we test must be stated with only P's public surface.  We restrict
        // to staking state invariants that do not require a reward token to be registered:
        // after withdrawAll, balanceOf(this) == 0 and totalSupply() decreased by exactly
        // the old balance.

        // Ensure c holds enough of the staking token by transferring from this contract.
        // transferFrom is part of the public ERC20 surface on c.stakingToken().
        // We assume the test contract has been funded with staking tokens by the harness.
        //
        // Record before values.
        uint256 beforeBal = c.balanceOf(thisAddr);
        uint256 beforeTotal = c.totalSupply();

        // Setup: approve and stake some amount to have a nonzero position.
        // We use the staking token's own public surface.
        IERC20 st = c.stakingToken();
        st.approve(address(c), amount);
        c.stake(amount);

        uint256 balAfterStake = c.balanceOf(thisAddr);
        uint256 totalAfterStake = c.totalSupply();

        require(balAfterStake == beforeBal + amount || balAfterStake == beforeBal);
        require(totalAfterStake == beforeTotal + amount || totalAfterStake == beforeTotal);

        // If staking succeeded (balance increased), then withdrawAll should clear it.
        if (c.balanceOf(thisAddr) > 0) {
            uint256 balBeforeWithdraw = c.balanceOf(thisAddr);
            uint256 totalBeforeWithdraw = c.totalSupply();

            c.withdrawAll(claim);

            // The general rule: withdrawAll removes the entire staked balance and
            // reduces totalSupply by exactly that balance.
            assert(
                c.balanceOf(thisAddr) == 0 &&
                c.totalSupply() == totalBeforeWithdraw - balBeforeWithdraw
            );
        } else {
            // If staking did not change the balance (e.g. zero or transferred amount),
            // the rule is vacuous; assert the unchanged consistency.
            assert(c.balanceOf(thisAddr) == 0 && c.totalSupply() == totalAfterStake);
        }
    }

    receive() external payable {}
}

