contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address rewardToken, uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0, "stake amount must be positive");
        require(address(this).balance >= stakeAmount, "insufficient balance");
        require(rewardToken != address(0), "reward token cannot be zero");

        // ensure reward token is registered
        c.addReward(rewardToken);

        // give test contract enough tokens to stake by using the staking token's transfer
        address stakingToken = c.stakingToken();
        (bool success, ) = stakingToken.call(abi.encodeWithSignature("transfer(address,uint256)", address(c), stakeAmount));
        require(success, "failed to seed c with staking tokens");

        // now stake as this contract
        c.stake(stakeAmount);

        // record before values
        uint256 beforeClaimable = c.claimableRewards(address(this), rewardToken);
        uint256 beforeBalance = c.balanceOf(address(this));

        // decide amount to withdraw: must be > 0 and <= current balance
        uint256 actualWithdraw = withdrawAmount % (beforeBalance + 1);
        if (actualWithdraw == 0) {
            actualWithdraw = 1;
        }

        // perform withdraw without claiming rewards
        c.withdraw(actualWithdraw, false);

        // read after values
        uint256 afterClaimable = c.claimableRewards(address(this), rewardToken);
        uint256 afterBalance = c.balanceOf(address(this));

        // The general rule: withdrawing without claiming must not reduce the user's claimable rewards,
        // and user balance must decrease by exactly the withdrawn amount.
        assert(afterClaimable >= beforeClaimable);
        assert(afterBalance == beforeBalance - actualWithdraw);
    }
}

