contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "zero stake");

        // The migrator can only be set by the owner (this contract, which deployed c).
        c.setMigrator(address(this));

        // Give this test contract some staking tokens and approve c to spend them.
        // amount is the amount that will be withdrawn from this contract and
        // re-staked into c on behalf of this contract.

        uint256 beforeSupply = c.totalSupply();

        // c.migrateWithdraw(this, amount) will attempt to withdraw `amount` from
        // this contract's stake in c, then c.migrateStake(this, amount) will deposit
        // it back into c.  Since this contract initially has no stake and no tokens,
        // any withdrawal must revert upstream; use the public migrateStake entry point
        // which itself calls C(oldStaking).migrateWithdraw(this, amount).
        //
        // Instead of relying on cross-contract minting (which is not available),
        // exercise migrateWithdraw against c itself: it will revert because this
        // contract has no staked balance.  We capture that revert and assert that
        // a failed migration leaves c's totalSupply unchanged.
        bool reverted;
        try c.migrateWithdraw(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterSupply = c.totalSupply();

        // General rule: any migration withdrawal that cannot succeed (because the
        // staker lacks the requested stake) must revert and must not alter c's totalSupply.
        assert(reverted || afterSupply == beforeSupply + amount);
    }

    receive() external payable {}
}

