        bool reverted;
        uint256 withdrawn;
        try c.migrateWithdraw(address(this), amount) {
            reverted = false;
            withdrawn = amount;
        } catch {
            reverted = true;
            withdrawn = 0;
        }

        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterSupply = c.totalSupply();

        // A withdrawal that succeeds must reduce the staker's balance by the withdrawn
        // amount and reduce totalSupply by that same amount; a reverted withdrawal must
        // leave both unchanged.  Express the unchanged case via the captured flag.
        assert(
            (reverted && afterBalance == beforeBalance && afterSupply == beforeSupply) ||
            (!reverted && afterBalance + withdrawn == beforeBalance && afterSupply + withdrawn == beforeSupply && withdrawn == amount)
        );
    }

    receive() external payable {}
}

