contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        require(withdrawAmount > 0);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        uint256 reserveBefore = c.stakingToken().balanceOf(address(c));

        bool staked;
        try c.stake(stakeAmount) { staked = true; } catch { staked = false; }

        if (staked) {
            require(withdrawAmount <= c.balanceOf(address(this)));
            uint256 balBeforeW = c.balanceOf(address(this));
            uint256 supplyBeforeW = c.totalSupply();
            uint256 reserveBeforeW = c.stakingToken().balanceOf(address(c));

            c.withdraw(withdrawAmount, false);

            assert(c.balanceOf(address(this)) == balBeforeW - withdrawAmount);
            assert(c.totalSupply() == supplyBeforeW - withdrawAmount);
            assert(c.stakingToken().balanceOf(address(c)) == reserveBeforeW - withdrawAmount);
        } else {
            assert(c.balanceOf(address(this)) == balBefore);
            assert(c.totalSupply() == supplyBefore);
            assert(c.stakingToken().balanceOf(address(c)) == reserveBefore);
        }
    }
}

